"""LiteLLM integration — universal-gateway trace ingestion.

LiteLLM is a unified router/proxy for ~100 LLM providers (OpenAI,
Anthropic, Bedrock, Azure, Gemini, Cohere, Mistral, Ollama, etc.). A
single PRISMtrace integration here covers every provider the user
routes through LiteLLM, without per-provider connector code.

LiteLLM exposes module-level callback lists:

  litellm.success_callback : list[Callable]
  litellm.failure_callback : list[Callable]

Each callback receives ``(kwargs, completion_response, start_time, end_time)``
on success, and ``(kwargs, exception, start_time, end_time)`` on failure.

This module:

1. Registers a single function on both lists that POSTs to ``/api/traces``
   with a ``framework="litellm"`` metadata tag and the underlying provider
   model so the trace renders as LiteLLM-routed in PRISMtrace.
2. Provides ``install(api_key, project_id, ...)`` as the documented entry
   point — one function call at SDK init time and every LiteLLM completion
   becomes a PRISMtrace trace.

Status: Supported (Universal Gateway). Real foundational support — the
callback wiring is the production-blessed extension point LiteLLM
documents for tracing tools.

Usage:

    import litellm
    from prismtrace import install_litellm
    install_litellm(api_key="pt-sk-...", project_id="<uuid>")

    # Every litellm.completion() / .acompletion() call is now traced.
    response = litellm.completion(
        model="gpt-4o",
        messages=[{"role": "user", "content": "hello"}],
    )
"""
from __future__ import annotations


import time
import uuid
from datetime import datetime
from typing import Any, Optional

import httpx
from ._config import DEFAULT_HOST, resolve_host
from ._session import resolve_session


_FRAMEWORK_TAG = "litellm"
_DEFAULT_ENDPOINT = DEFAULT_HOST


def _ambient_session_factory(kwargs: dict) -> str:
    """Default session factory: the ambient session, else a per-completion id.

    Read per completion rather than once at install time, so a gateway
    installed at startup still groups the calls a request makes under whatever
    session that request opened.
    """
    return resolve_session(None, str(uuid.uuid4()))


class _LiteLLMTraceForwarder:
    """Holds config + HTTP client; appended once to litellm's callback lists."""

    def __init__(
        self,
        api_key: str,
        project_id: str,
        endpoint: Optional[str],
        agent_name: str,
        session_id_factory: Optional[Any] = None,
        timeout: int = 10,
    ) -> None:
        self.api_key = api_key
        self.project_id = project_id
        self.endpoint = resolve_host(endpoint)
        self.agent_name = agent_name
        # Session identification: by default each completion gets its own
        # session UUID. Pass a callable for custom session correlation
        # (e.g. group all completions in a user request under one id).
        self.session_id_factory = session_id_factory or _ambient_session_factory
        # Seconds per POST; the SDK fails open, so this bounds silent loss
        # against a slow backend (KAN-47). Same argument the voice tracer takes.
        self.timeout = timeout
        self._closed = False
        self._http = httpx.Client(
            headers={
                "X-PRISMtrace-Key": api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )

    def __call__(
        self,
        kwargs: dict,
        completion_response: Any = None,
        start_time: Any = None,
        end_time: Any = None,
    ) -> None:
        """Forward one LiteLLM completion event to PRISMtrace."""
        try:
            self._forward(kwargs, completion_response, start_time, end_time, error=None)
        except Exception as exc:
            # Tracing must never break the user's request. Same fail-open
            # policy used by the LangChain handler.
            print(f"[prismtrace litellm] forward failed: {exc}")

    def on_failure(
        self,
        kwargs: dict,
        exception: BaseException,
        start_time: Any = None,
        end_time: Any = None,
    ) -> None:
        """LiteLLM failure callback — same shape with `exception` instead of response."""
        try:
            self._forward(kwargs, None, start_time, end_time, error=str(exception))
        except Exception as exc:
            print(f"[prismtrace litellm] failure forward failed: {exc}")

    # ------------------------------------------------------------------
    # Internals
    # ------------------------------------------------------------------

    def _forward(
        self,
        kwargs: dict,
        completion_response: Any,
        start_time: Any,
        end_time: Any,
        error: Optional[str],
    ) -> None:
        underlying_model = (kwargs or {}).get("model") or "unknown"
        # Tag the model field so the server architecture extractor maps the
        # run to framework=litellm without losing the underlying model.
        tagged_model = f"{_FRAMEWORK_TAG}:{underlying_model}"

        latency_ms = _latency_ms(start_time, end_time)
        input_messages = _normalize_messages((kwargs or {}).get("messages") or [])
        output_message = _extract_completion_text(completion_response) if not error else f"[litellm error] {error}"

        token_input = _safe_int(_dig(completion_response, ("usage", "prompt_tokens")))
        token_output = _safe_int(_dig(completion_response, ("usage", "completion_tokens")))

        # Try to honor LiteLLM's metadata channel: callers can stuff a
        # session id under `metadata` per call. Fall back to factory.
        per_call_meta = (kwargs or {}).get("metadata") or {}
        session_id = per_call_meta.get("session_id") or self.session_id_factory(kwargs)

        payload = {
            "project_id": self.project_id,
            "model": tagged_model,
            "input_messages": input_messages,
            "output_message": output_message,
            "latency_ms": latency_ms,
            "token_count_input": token_input,
            "token_count_output": token_output,
            "session_id": session_id,
            "metadata": {
                "framework": "litellm",
                "agent_name": self.agent_name,
                "agent_id": self.agent_name,
                "source": "litellm-gateway",
                "session_id": session_id,
                "underlying_provider_model": underlying_model,
                "error": error,
            },
        }
        self._http.post(f"{self.endpoint}/api/traces", json=payload)

    # ------------------------------------------------------------------
    # Lifecycle
    # ------------------------------------------------------------------

    def close(self) -> None:
        """Release the HTTP connection pool. Idempotent."""
        if self._closed:
            return
        self._closed = True
        try:
            self._http.close()
        except Exception:
            pass

    def __enter__(self) -> "_LiteLLMTraceForwarder":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False


def install(
    api_key: str,
    project_id: str,
    endpoint: Optional[str] = None,
    agent_name: str = "litellm-gateway",
    session_id_factory: Optional[Any] = None,
    timeout: int = 10,
) -> _LiteLLMTraceForwarder:
    """Register a PRISMtrace forwarder on LiteLLM's success/failure callback lists.

    Returns the forwarder instance so callers can introspect or unregister
    by removing it from ``litellm.success_callback`` / ``failure_callback``.

    Idempotent: calling ``install()`` twice with the same args replaces the
    previous forwarder rather than stacking duplicates.
    """
    try:
        import litellm  # type: ignore[import-not-found]
    except ImportError as exc:
        raise ImportError(
            "litellm is required. Install with: pip install litellm"
        ) from exc

    forwarder = _LiteLLMTraceForwarder(
        api_key=api_key,
        project_id=project_id,
        endpoint=endpoint,
        agent_name=agent_name,
        session_id_factory=session_id_factory,
        timeout=timeout,
    )

    # Remove any previously-installed PRISMtrace forwarder so re-installing
    # with new credentials doesn't double-post.
    def _filter(lst: list) -> list:
        return [cb for cb in lst if not isinstance(cb, _LiteLLMTraceForwarder)]

    if hasattr(litellm, "success_callback"):
        litellm.success_callback = _filter(litellm.success_callback or []) + [forwarder]
    if hasattr(litellm, "failure_callback"):
        litellm.failure_callback = _filter(litellm.failure_callback or []) + [forwarder.on_failure]

    return forwarder


# ----------------------------------------------------------------------
# Helpers (module-level so they're cheap to unit-test in isolation)
# ----------------------------------------------------------------------

def _latency_ms(start: Any, end: Any) -> int:
    """LiteLLM passes either datetime or float epoch seconds depending on version."""
    if start is None or end is None:
        return 0
    try:
        if isinstance(start, datetime) and isinstance(end, datetime):
            return int((end - start).total_seconds() * 1000)
        return int((float(end) - float(start)) * 1000)
    except (TypeError, ValueError):
        return 0


def _normalize_messages(messages: Any) -> list:
    """Coerce arbitrary message shapes into [{role, content}, ...]."""
    if not isinstance(messages, list):
        return []
    out = []
    for m in messages:
        if isinstance(m, dict):
            out.append({"role": str(m.get("role", "user")), "content": str(m.get("content", ""))[:16000]})
    return out


def _extract_completion_text(response: Any) -> str:
    if response is None:
        return ""
    # LiteLLM normalises to OpenAI-style ModelResponse — try the documented path.
    for path in (("choices", 0, "message", "content"), ("choices", 0, "text")):
        v = _dig(response, path)
        if v:
            return str(v)[:16000]
    return str(response)[:16000]


def _dig(obj: Any, path: tuple) -> Any:
    cur = obj
    for step in path:
        try:
            cur = cur[step] if isinstance(step, int) else (getattr(cur, step, None) if not isinstance(cur, dict) else cur.get(step))
        except (KeyError, IndexError, AttributeError, TypeError):
            return None
        if cur is None:
            return None
    return cur


def _safe_int(v: Any) -> int:
    try:
        return int(v) if v is not None else 0
    except (TypeError, ValueError):
        return 0
